export class DeliveryService {
    private readonly outbox: NotificationOutbox;
    private readonly policy: DeliveryPolicy;
    private readonly now: () => number;

    constructor(outbox: NotificationOutbox, policy: DeliveryPolicy, now = () => Date.now()) {
        if (!Number.isInteger(policy.maxAttempts) || policy.maxAttempts < 1) {
            throw new Error('Delivery attempt limit must be positive');
        }
        if (!Number.isInteger(policy.batchSize) || policy.batchSize < 1 || policy.batchSize > 100) {
            throw new Error('Delivery batch size is invalid');
        }
        if (!Number.isInteger(policy.initialDelay) || policy.initialDelay < 1) {
            throw new Error('Delivery initial delay is invalid');
        }
        if (!Number.isInteger(policy.maximumDelay) || policy.maximumDelay < policy.initialDelay) {
            throw new Error('Delivery maximum delay is invalid');
        }
        this.outbox = outbox;
        this.policy = {...policy};
        this.now = now;
    }

    ready(): OutboxMessage[] {
        return this.outbox.due(this.now(),this.policy.batchSize);
    }

    begin(id: string): OutboxMessage {
        return this.outbox.claim(id,this.now());
    }

    succeed(id: string): DeliveryReceipt {
        const message = this.outbox.complete(id,this.now());
        return {
            messageId:message.id,
            recipient:message.recipient,
            deliveredAt:message.deliveredAt!,
            attempts:message.attempts,
        };
    }

    reject(id: string, reason: string): DeliveryFailure {
        if (!reason.trim()) {
            throw new Error('Delivery failure requires a reason');
        }
        const current = this.outbox.get(id);
        const delay = Math.min(this.policy.maximumDelay,this.policy.initialDelay * 2 ** (current.attempts - 1));
        const failed = this.outbox.fail(id,reason,this.now()+delay,this.policy.maxAttempts);
        return {
            messageId:id,
            reason,
            nextAttemptAt:failed.nextAttemptAt,
            exhausted:failed.state === 'failed',
        };
    }

    receipts(recipient?: string): DeliveryReceipt[] {
        return this.outbox.list('delivered')
            .filter(message=>recipient===undefined || message.recipient===recipient)
            .map(message=>({
                messageId:message.id,
                recipient:message.recipient,
                deliveredAt:message.deliveredAt!,
                attempts:message.attempts,
            }));
    }

    health(): {pending: number; delivering: number; delivered: number; failed: number; exhaustedIds: string[]} {
        return {
            ...this.outbox.counts(),
            exhaustedIds:this.outbox.list('failed').map(message=>message.id).sort(),
        };
    }
}

