export class NotificationOutbox {
    private readonly values = new Map<string,OutboxMessage>();
    private readonly logicalIds = new Map<string,string>();

    enqueue(input: Omit<OutboxMessage,'state'|'attempts'|'nextAttemptAt'>): OutboxMessage {
        const currentId = this.logicalIds.get(input.logicalId);
        if (currentId !== undefined) {
            const current = this.get(currentId);
            if (current.recipient !== input.recipient || current.template !== input.template) {
                throw new Error('Logical notification reused for a different recipient or template');
            }
            return current;
        }
        if (this.values.has(input.id)) {
            throw new Error('Outbox identifier already exists');
        }
        const message: OutboxMessage = {
            ...input,
            data:{...input.data},
            state:'pending',
            attempts:0,
            nextAttemptAt:input.createdAt,
        };
        this.values.set(message.id,message);
        this.logicalIds.set(message.logicalId,message.id);
        return copyMessage(message);
    }

    get(id: string): OutboxMessage {
        const value = this.values.get(id);
        if (!value) {
            throw new Error('Outbox message not found');
        }
        return copyMessage(value);
    }

    due(now: number, limit: number): OutboxMessage[] {
        if (!Number.isInteger(limit) || limit < 1) {
            throw new Error('Outbox limit must be positive');
        }
        return [...this.values.values()]
            .filter(value=>value.state==='pending' && value.nextAttemptAt<=now)
            .sort((left,right)=>left.nextAttemptAt-right.nextAttemptAt || left.id.localeCompare(right.id))
            .slice(0,limit)
            .map(copyMessage);
    }

    claim(id: string, now: number): OutboxMessage {
        const value = this.get(id);
        if (value.state !== 'pending' || value.nextAttemptAt > now) {
            throw new Error('Outbox message is not ready');
        }
        const claimed: OutboxMessage = {
            ...value,
            state:'delivering',
            attempts:value.attempts+1,
        };
        this.values.set(id,claimed);
        return copyMessage(claimed);
    }

    complete(id: string, now: number): OutboxMessage {
        const value = this.get(id);
        if (value.state !== 'delivering') {
            throw new Error('Outbox message is not being delivered');
        }
        const completed: OutboxMessage = {
            ...value,
            state:'delivered',
            deliveredAt:now,
            lastError:undefined,
        };
        this.values.set(id,completed);
        return copyMessage(completed);
    }

    fail(id: string, error: string, retryAt: number, maxAttempts: number): OutboxMessage {
        const value = this.get(id);
        if (value.state !== 'delivering' || !Number.isInteger(maxAttempts) || maxAttempts<1) {
            throw new Error('Outbox failure transition is invalid');
        }
        const failed: OutboxMessage = {
            ...value,
            state:value.attempts>=maxAttempts ? 'failed' : 'pending',
            nextAttemptAt:retryAt,
            lastError:error,
        };
        this.values.set(id,failed);
        return copyMessage(failed);
    }

    list(state?: OutboxMessage['state']): OutboxMessage[] {
        return [...this.values.values()]
            .filter(value=>state===undefined || value.state===state)
            .map(copyMessage);
    }

    counts(): Record<OutboxMessage['state'],number> {
        const result = {pending:0,delivering:0,delivered:0,failed:0};
        for (const message of this.values.values()) {
            result[message.state] += 1;
        }
        return result;
    }
}

