export class SettlementService {
    private readonly store: SettlementStore;
    private readonly makeId: () => string;
    private readonly now: () => number;

    constructor(store: SettlementStore, makeId: () => string, now=()=>Date.now()) {
        this.store = store;
        this.makeId = makeId;
        this.now = now;
    }

    prepare(accountId: string, orders: Order[], feeBasisPoints: number): SettlementBatch {
        const lines = orders.map(order=>settlementLine(order,feeBasisPoints));
        const batch = createSettlement(this.makeId(),accountId,lines,this.now());
        return this.store.create(batch);
    }

    approve(id: string, memberId: string): SettlementBatch {
        const batch = approveSettlement(this.get(id),memberId,this.now());
        return this.store.update(batch);
    }

    pay(id: string, reference: string): SettlementBatch {
        const batch = paySettlement(this.get(id),reference,this.now());
        return this.store.update(batch);
    }

    get(id: string): SettlementBatch {
        const batch = this.store.get(id);
        if (!batch) {
            throw new Error('Settlement not found');
        }
        return batch;
    }

    list(accountId?: string, state?: SettlementBatch['state']): SettlementBatch[] {
        return this.store.list(accountId).filter(batch=>state===undefined || batch.state===state);
    }

    summary(accountId: string): { draftCents: number; approvedCents: number; paidCents: number; count: number } {
        const batches = this.list(accountId);
        const totals = {draftCents:0,approvedCents:0,paidCents:0,count:batches.length};
        for (const batch of batches) {
            const amount = settlementTotal(batch).cents;
            if (batch.state === 'draft') totals.draftCents += amount;
            if (batch.state === 'approved') totals.approvedCents += amount;
            if (batch.state === 'paid') totals.paidCents += amount;
        }
        return totals;
    }

    exportRows(accountId: string): Array<Record<string,unknown>> {
        return this.list(accountId).map(batch=>({
            id:batch.id,
            accountId:batch.accountId,
            state:batch.state,
            orderCount:batch.lines.length,
            payableCents:settlementTotal(batch).cents,
            createdAt:batch.createdAt,
            approvedBy:batch.approvedBy,
            paidAt:batch.paidAt,
        }));
    }
}

