export class AuditService {
    private readonly store: AuditStore;
    private readonly now: () => number;
    private readonly id: () => string;

    constructor(store: AuditStore, id: () => string, now = () => Date.now()) {
        this.store = store;
        this.id = id;
        this.now = now;
    }

    record(action: string, actorId: string, payload: Record<string, unknown>): AuditEntry {
        if (!action.trim() || !actorId.trim()) {
            throw new Error('Audit action and actor are required');
        }
        const entry = safeAudit({
            id: this.id(),
            action,
            actorId,
            payload,
            createdAt: this.now(),
        });
        return this.store.append(entry);
    }

    list(query: AuditQuery = {}): AuditEntry[] {
        if (query.from !== undefined && query.to !== undefined && query.from > query.to) {
            throw new Error('Audit interval is invalid');
        }
        return this.store.all().filter(entry => {
            if (query.action !== undefined && query.action !== entry.action) return false;
            if (query.actorId !== undefined && query.actorId !== entry.actorId) return false;
            if (query.from !== undefined && entry.createdAt < query.from) return false;
            if (query.to !== undefined && entry.createdAt > query.to) return false;
            return true;
        });
    }

    topics(query: AuditQuery = {}): string[] {
        return [...new Set(this.list(query).map(entry => auditTopic(entry.action)))].sort();
    }

    statistics(query: AuditQuery = {}): { count: number; actors: number; actions: Record<string, number> } {
        const entries = this.list(query);
        const actions: Record<string, number> = {};
        for (const entry of entries) {
            actions[entry.action] = (actions[entry.action] ?? 0) + 1;
        }
        return {
            count: entries.length,
            actors: new Set(entries.map(entry => entry.actorId)).size,
            actions,
        };
    }
}

