export function redactSensitive(value: unknown): unknown {
    if (Array.isArray(value)) return value.map(item => redactSensitive(item));
    if (!value || typeof value !== 'object') return value;
    const result: Record<string, unknown> = {};
    for (const [key, item] of Object.entries(value)) result[key] = isSensitiveKey(key) ? '[REDACTED]' : redactSensitive(item);
    return result;
}

export class EventStore {
    private readonly values: EventRecord[] = [];
    append(event: EventRecord): EventRecord { if (this.values.some(item => item.id === event.id)) throw new Error('Duplicate event'); this.values.push({ ...event, payload: { ...event.payload } }); return event; }
    all(): EventRecord[] { return this.values.map(event => ({ ...event, payload: { ...event.payload } })); }
    topic(topic: string): EventRecord[] { return this.all().filter(event => event.topic === topic); }
    actor(actorId: string): EventRecord[] { return this.all().filter(event => event.actorId === actorId); }
    since(createdAt: number): EventRecord[] { return this.all().filter(event => event.createdAt >= createdAt); }
    count(): number { return this.values.length; }
    latest(): EventRecord | undefined { return this.values[this.values.length - 1]; }
    clear(): void { this.values.length = 0; }
}
